fn bar_h(i: i32, t: i32) -> i32 {
    let mut hsh: i32 = (i * 40503 + t / 4) * 1103515245 + 12345;
    hsh = (hsh >> 13) ^ hsh;
    if hsh < 0 { hsh = 0 - hsh; }
    40 + hsh % 120
}

fn frame(t: i32) {
    let h: i32 = host::display::height();
    if t % 30 == 0 {
        host::audio::tone(45, 120, 0);
    }
    let boost: i32 = 30 - t % 30;
    host::display::clear(0x080808);
    host::display::draw_string(16, 16, "VISUALIZER", 0xffffff, 2);
    let mut i: i32 = 0;
    while i < 8 {
        let bh: i32 = bar_h(i, t) + boost * 2;
        host::display::fill_rect(16 + i * 62, h - 20 - bh, 48, bh, 0x00ffcc);
        i = i + 1;
    }
    host::display::present();
}
